module.exports = function(RED) {
    "use strict";

    const fs = require("fs").promises;
    const {execFile} = require("child_process");
    const {promisify} = require("util");
    const run = promisify(execFile);

    async function checkSelectedBranch(directory, msg) {
        if (!msg.git || typeof msg.git.path !== "string" || typeof msg.git.ref !== "string") {
            return;
        }
        if (await fs.realpath(msg.git.path) !== directory) {
            return;
        }
        let stdout;
        try {
            ({stdout} = await run("git", ["symbolic-ref", "--quiet", "HEAD"], {cwd: directory}));
        } catch (error) {
            throw new Error("The selected Git branch is not checked out in this directory", {cause: error});
        }
        if (stdout.trim() !== msg.git.ref) {
            throw new Error("The selected Git branch is not checked out in this directory");
        }
    }

    function CodexAgentNode(config) {
        RED.nodes.createNode(this, config);
        const node = this;
        let active;

        node.on("input", async function(msg, send, done) {
            if (active) {
                done(new Error("Codex agent is already processing a message"));
                return;
            }
            const controller = new AbortController();
            active = controller;
            try {
                const rawDirectory = RED.util.evaluateNodeProperty(config.directory || "git.path", config.directoryType || "msg", node, msg);
                const prompt = RED.util.evaluateNodeProperty(config.prompt || "payload", config.promptType || "msg", node, msg);
                if (typeof rawDirectory !== "string" || !rawDirectory.trim()) {
                    throw new Error("Codex working directory must be a path");
                }
                if (typeof prompt !== "string" || !prompt.trim()) {
                    throw new Error("Codex prompt must be a non-empty string");
                }
                const directory = await fs.realpath(rawDirectory);
                if (!(await fs.stat(directory)).isDirectory()) {
                    throw new Error("Codex working directory must be a directory");
                }
                await checkSelectedBranch(directory, msg);

                const model = typeof config.model === "string" ? config.model.trim() : "";
                const modelReasoningEffort = config.modelReasoningEffort || "";
                if (modelReasoningEffort && !["minimal", "low", "medium", "high", "xhigh", "max", "ultra", "persistent"].includes(modelReasoningEffort)) {
                    throw new Error("Invalid Codex reasoning effort");
                }
                const {Codex} = await import("@openai/codex-sdk");
                const thread = new Codex().startThread({
                    ...(model ? {model} : {}),
                    ...(modelReasoningEffort ? {modelReasoningEffort} : {}),
                    workingDirectory: directory,
                    sandboxMode: config.allowEdits === true ? "workspace-write" : "read-only",
                    approvalPolicy: "never",
                    networkAccessEnabled: false
                });
                node.status({fill: "blue", shape: "dot", text: "codex running"});
                const result = await thread.run(prompt, {signal: controller.signal});
                msg.payload = result.finalResponse;
                msg.codex = {threadId: thread.id, usage: result.usage};
                node.status({});
                send(msg);
                done();
            } catch (error) {
                node.status({fill: "red", shape: "ring", text: "codex error"});
                done(error);
            } finally {
                active = null;
            }
        });

        node.on("close", function() {
            if (active) {
                active.abort();
            }
        });
    }

    RED.nodes.registerType("codex agent", CodexAgentNode);
};
